'use strict';
const E=EditorEngine,$=id=>document.getElementById(id),urls=new Set();
const state={clips:[],assets:{},cues:[],srt:'',jobs:[],busy:false,loading:0,controller:null,preview:null,previewToken:0,frame:0,tool:'trim'};
const configIds=['export-mode','bitrate','fps','output-prefix','output-suffix','resolution','fit','background','mark-text','mark-size','mark-alpha','mark-x','mark-y','mark-ends','original-volume','music-volume','music-offset','music-loop','fade-in','fade-out','ends-audio','cover-title','cover-color','cover-size','cover-format','intro-duration','outro-duration','subtitle-font','subtitle-size','subtitle-color','subtitle-y','subtitle-offset','subtitle-bg'];
const numericIds=new Set(['bitrate','fps','resolution','mark-size','mark-alpha','mark-x','mark-y','original-volume','music-volume','music-offset','fade-in','fade-out','cover-size','intro-duration','outro-duration','subtitle-size','subtitle-y','subtitle-offset']);
function config(){const c={};for(const id of configIds){const input=$(id);c[id]=input.type==='checkbox'?input.checked:numericIds.has(id)?Number(input.value):input.value}c.ratios=[...document.querySelectorAll('[name=ratio]:checked')].map(n=>n.value);c.formats=[...document.querySelectorAll('[name=format]:checked')].map(n=>n.dataset.ext);return c}
function validate(c){for(const id of numericIds){const n=c[id],input=$(id);if(!Number.isFinite(n)||(input.min!==''&&n<Number(input.min))||(input.max!==''&&n>Number(input.max)))throw Error(input.closest('label')?.textContent.trim().split('\n')[0]+' 数值超出范围')}if(!c.ratios.length)throw Error('请在多画幅工具中至少选择一种画幅');if(!c.formats.length)throw Error('请至少选择一种当前浏览器支持的视频格式');if(state.loading)throw Error('素材仍在读取，请稍等');if($('srt-text').value!==state.srt)throw Error('字幕已修改，请先点击「解析并应用字幕」');return c}
function url(file){const u=URL.createObjectURL(file);urls.add(u);return u}
function message(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error)}
function safe(s){return s.replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').trim().slice(0,170)||'成片'}
function base(s){return s.replace(/\.[^.]+$/,'')}
function size(n){return n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB'}
function time(n){return Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0')}
function button(text,fn,cls='mini'){const b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=fn;return b}
function route(){const key=location.hash.slice(1);state.tool=['trim','resize','watermark','audio','cover','subtitle','presets','tasks'].includes(key)?key:'trim';const copy={trim:['裁剪与拼接','截取精彩片段，拖动排序，组合成一条完整作品。'],resize:['多画幅转换','一份视频，多种画幅。为不同发布位置调整构图。'],watermark:['水印编辑器','拖动摆放品牌水印，让每条成片保持一致。'],audio:['音乐与混音','添加背景音乐，调整原声比例，让声音自然衔接。'],cover:['封面与片头','挑选封面帧，添加统一片头与尾版。'],subtitle:['字幕工具','导入 SRT，统一字幕的字体、位置与时间。'],presets:['合成方案库','把重复使用的参数和品牌素材保存下来。'],tasks:['导出任务','查看每条成片的进度，下载结果或单独重试。']};$('tool-title').textContent=copy[state.tool][0];$('tool-description').textContent=copy[state.tool][1];document.querySelectorAll('[data-panel]').forEach(n=>n.hidden=n.dataset.panel!==state.tool);document.querySelectorAll('[data-tool]').forEach(n=>{n.classList.toggle('active',n.dataset.tool===state.tool);if(n.dataset.tool===state.tool)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});drawPreview();if(state.tool==='presets')renderPresets()}
window.addEventListener('hashchange',route);
function lock(){document.querySelectorAll('input,select,textarea,button').forEach(n=>{if(n.id==='cancel')return;n.disabled=state.busy||n.dataset.unsupported==='true'});$('export').disabled=state.busy||state.loading>0||!state.clips.length;$('download-all').disabled=state.busy||!state.jobs.some(j=>j.status==='成功');$('cancel').hidden=!state.busy}
function setLabels(){for(const id of ['mark-size','mark-alpha','original-volume','music-volume'])$(id+'-value').textContent=$(id).value+'%'}
const assetVersion={};
async function prepareAsset(kind,file){const u=url(file),isVideo=PixelCompat.mediaKind(file)==='video';const a={file,url:u,isVideo};try{if(kind==='music'){if(!file.type.startsWith('audio/')&&!/\.(mp3|wav|m4a|aac|ogg|flac)$/i.test(file.name))throw Error('请选择音频文件');return a}if(isVideo){if(kind==='mark')throw Error('水印需为图片');const v=await Studio.loadVideo(u,undefined,true);a.duration=v.duration;a.width=v.videoWidth;a.height=v.videoHeight;Studio.releaseVideo(v)}else{a.image=await Studio.loadImage(u);a.width=a.image.naturalWidth;a.height=a.image.naturalHeight}return a}catch(e){URL.revokeObjectURL(u);urls.delete(u);throw e}}
async function setAsset(kind,file){const id=assetVersion[kind]=(assetVersion[kind]||0)+1;if(!file){delete state.assets[kind];renderAssets();await refreshPreview();estimate();return}state.loading++;lock();try{const a=await prepareAsset(kind,file);if(id===assetVersion[kind]){state.assets[kind]=a;renderAssets();await refreshPreview();estimate();message('已添加 '+file.name)}}catch(e){message(e.message,true)}finally{state.loading--;lock()}}
function renderAssets(){for(const kind of ['mark','intro','outro','music'])$(kind+'-name').textContent=state.assets[kind]?.file.name||({mark:'透明 PNG 效果更好',intro:'未添加片头',outro:'未添加尾版',music:'未添加背景音乐'}[kind]);$('music-player').hidden=!state.assets.music;if(state.assets.music){if($('music-player').src!==state.assets.music.url)$('music-player').src=state.assets.music.url}else{$('music-player').pause();$('music-player').removeAttribute('src');$('music-player').load()}renderTimeline();renderPreviewSelect()}
async function addClips(files){if(state.busy)return;state.loading++;lock();let errors=[];for(const file of files){if(PixelCompat.mediaKind(file)!=='video'){errors.push(file.name+'：请选择视频');continue}const u=url(file);try{const v=await Studio.loadVideo(u,undefined,true);state.clips.push({id:PixelCompat.id(),file,url:u,start:0,end:v.duration,duration:v.duration,width:v.videoWidth,height:v.videoHeight,focusX:.5,focusY:.5});Studio.releaseVideo(v)}catch(e){URL.revokeObjectURL(u);urls.delete(u);errors.push(file.name+'：'+e.message)}}state.loading--;renderClips();estimate();lock();message(errors.length?errors.join('；'):'已添加 '+state.clips.length+' 条视频',errors.length>0)}
function renderClips(){const list=$('clip-list');list.replaceChildren();state.clips.forEach((clip,i)=>{const row=document.createElement('div');row.className='clip';row.draggable=!state.busy;row.dataset.id=clip.id;const head=document.createElement('div');head.className='clip-head';const handle=document.createElement('span');handle.className='handle';handle.textContent='⠿';const info=document.createElement('div');info.className='clip-name';info.textContent=clip.file.name;const meta=document.createElement('small');meta.textContent=clip.width+' × '+clip.height+' · '+time(clip.duration)+' · '+size(clip.file.size);info.append(meta);head.append(handle,info,button('↑',()=>move(i,-1)),button('↓',()=>move(i,1)),button('×',()=>{state.clips.splice(i,1);renderClips();estimate()}));row.append(head);const trim=document.createElement('div');trim.className='clip-times';for(const key of ['start','end']){const label=document.createElement('label');label.textContent=key==='start'?'开始秒':'结束秒';const input=document.createElement('input');input.type='number';input.min=0;input.max=clip.duration;input.step=.01;input.value=Number(clip[key].toFixed(2));input.setAttribute('aria-label',clip.file.name+' '+label.textContent);input.onchange=()=>{const value=Number(input.value);if(!Number.isFinite(value)||value<0||value>clip.duration||(key==='start'?value>=clip.end:value<=clip.start)){input.value=Number(clip[key].toFixed(2));message('开始时间需早于结束时间，且都在视频时长范围内',true);return}clip[key]=value;renderTimeline();estimate();drawPreview()};label.append(input);trim.append(label)}trim.append(button('预览',()=>{$('preview-select').value=clip.id;refreshPreview()}));row.append(trim);row.ondragstart=e=>e.dataTransfer.setData('text/plain',clip.id);row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();if(state.busy)return;const from=state.clips.findIndex(x=>x.id===e.dataTransfer.getData('text/plain'));if(from<0)return;const [moved]=state.clips.splice(from,1);state.clips.splice(i,0,moved);renderClips();estimate()};list.append(row)});$('drop-zone').hidden=state.clips.length>0;renderPreviewSelect();renderTimeline();lock()}
function move(i,d){if(state.busy||i+d<0||i+d>=state.clips.length)return;[state.clips[i],state.clips[i+d]]=[state.clips[i+d],state.clips[i]];renderClips();estimate()}
function renderTimeline(){const c=config();$('timeline').replaceChildren();const add=(text,end)=>{const s=document.createElement('span');s.textContent=text;if(end)s.className='end';$('timeline').append(s)};if(state.assets.intro)add('片头 · '+(state.assets.intro.isVideo?state.assets.intro.duration:c['intro-duration']).toFixed(1)+'s',true);state.clips.forEach((v,i)=>add((i+1)+'. '+base(v.file.name)+' · '+(v.end-v.start).toFixed(1)+'s'));if(state.assets.outro)add('尾版 · '+(state.assets.outro.isVideo?state.assets.outro.duration:c['outro-duration']).toFixed(1)+'s',true)}
function renderPreviewSelect(){const select=$('preview-select'),old=select.value;select.replaceChildren();if(state.assets.intro)select.add(new Option('片头','intro'));state.clips.forEach(v=>select.add(new Option(v.file.name,v.id)));if(state.assets.outro)select.add(new Option('尾版','outro'));if([...select.options].some(o=>o.value===old))select.value=old;else if(state.clips.length)select.value=state.clips[0].id;if(!state.preview||state.preview.key!==select.value)refreshPreview()}
function stopPreview(){cancelAnimationFrame(state.frame);state.preview?.video?.pause();$('play').textContent='播放'}
async function refreshPreview(){const token=++state.previewToken;stopPreview();if(state.preview?.video)Studio.releaseVideo(state.preview.video);state.preview=null;const key=$('preview-select').value;const clip=state.clips.find(x=>x.id===key);const a=clip||state.assets[key];$('canvas-empty').hidden=false;if(!a){$('canvas-empty').textContent='添加视频后预览';return}let v;try{const isVideo=!!clip||a.isVideo;if(isVideo)v=await Studio.loadVideo(a.url,undefined,true);if(token!==state.previewToken){Studio.releaseVideo(v);return}const source=v||a.image,segment={...a,kind:clip?'clip':key};if(v){v.id='original';v.style.cssText='max-width:100%;max-height:460px';$('original-wrap').replaceChildren(v);v.onseeked=drawPreview;v.onended=()=>{$('play').textContent='播放';drawPreview()};if(clip&&clip.start>0)await E.seek(v,clip.start)}if(token!==state.previewToken){Studio.releaseVideo(v);return}state.preview={key,source,video:v,segment};$('canvas-empty').hidden=true;$('play').disabled=!v||state.busy;$('seek').disabled=!v||state.busy;$('original-wrap').hidden=!$('compare').checked||!v;$('preview-grid').classList.toggle('comparing',$('compare').checked&&!!v);drawPreview()}catch(e){Studio.releaseVideo(v);if(token===state.previewToken)message(e.message,true)}}
function previewOffset(){const c=config(),p=state.preview;if(!p||p.segment.kind==='intro')return 0;let total=state.assets.intro?(state.assets.intro.isVideo?state.assets.intro.duration:c['intro-duration']):0;const chosen=state.clips.findIndex(v=>v.id===p.key);if(p.segment.kind==='outro')return total+(c['export-mode']==='join'?state.clips.reduce((s,v)=>s+v.end-v.start,0):(state.clips[0]?.end-state.clips[0]?.start||0));if(c['export-mode']==='join')for(let i=0;i<chosen;i++)total+=state.clips[i].end-state.clips[i].start;return total}
function drawPreview(){cancelAnimationFrame(state.frame);const p=state.preview;if(!p)return;try{const c=config(),clip=state.clips.find(x=>x.id===p.key);if(clip)p.segment={...clip,kind:'clip'};const basis=c['export-mode']==='batch'&&p.segment.kind==='clip'?p.segment:state.clips[0]||p.segment;const sw=basis.width,sh=basis.height;const [w,h]=E.dimensions(sw,sh,$('preview-ratio').value,c.resolution);const scale=Math.min(1,960/w,720/h);const canvas=$('canvas');if(canvas.width!==Math.round(w*scale)||canvas.height!==Math.round(h*scale)){canvas.width=Math.round(w*scale);canvas.height=Math.round(h*scale)}const current=p.video?p.video.currentTime:0;E.draw(canvas.getContext('2d'),p.source,canvas.width,canvas.height,c,state.assets,p.segment,previewOffset()+Math.max(0,current-(p.segment.start||0)),state.cues,state.tool==='cover');if(p.video){$('seek').value=current/p.video.duration*100;$('time').textContent=time(current)+' / '+time(p.video.duration)}else $('time').textContent=(p.segment.isVideo?p.segment.duration:c[p.segment.kind+'-duration'])+' 秒';$('preview-hint').textContent='预览静音 · 输出 '+w+' × '+h+'。'+(state.tool==='watermark'?'拖动放置水印。':state.tool==='resize'?'填满模式下可拖动调整裁切。':'选帧预览；导出按设置的片段区间生成。')}catch(e){message(e.message,true)}if(p.video&&!p.video.paused)state.frame=requestAnimationFrame(drawPreview)}
function estimate(){try{const c=config(),groups=c['export-mode']==='join'?[state.clips]:state.clips.map(v=>[v]);let total=0;for(const clips of groups)total+=E.segments(clips,c,state.assets).reduce((s,x)=>s+x.seconds,0);const count=groups.length*c.ratios.length*c.formats.length;const bytes=total*(c.bitrate+128000)/8*c.ratios.length*c.formats.length;$('estimate').textContent=state.clips.length?'预计 '+count+' 个视频 · 合成总片长 '+time(total*c.ratios.length*c.formats.length)+' · 总体积约 '+size(bytes):'添加素材后显示数量、时长与预估体积。';const large=state.clips.reduce((s,v)=>s+v.file.size,0)>524288000||total>600;$('large-warning').hidden=!large;$('large-warning').textContent='当前素材较大或较长，实时合成会占用较多内存。建议分批处理、降低分辨率；单任务成片上限 1 GB。'}catch(e){$('estimate').textContent=e.message}}
function applySRT(){try{const cues=E.parseSRT($('srt-text').value);state.srt=$('srt-text').value;state.cues=cues;$('srt-state').textContent='已应用 '+cues.length+' 条字幕';drawPreview();message('字幕已更新')}catch(e){$('srt-state').textContent=e.message;message(e.message,true)}}
function snapshotJobs(){const c=validate(config());if(!state.clips.length)throw Error('请先添加视频');const groups=c['export-mode']==='join'?[state.clips]:state.clips.map(v=>[v]);const formats=Studio.formats().filter(f=>f.mime&&c.formats.includes(f.ext)),jobs=[];for(const group of groups)for(const ratio of c.ratios)for(const format of formats){E.segments(group,c,state.assets);const name=safe(c['output-prefix']+(c['export-mode']==='join'?'拼接作品':base(group[0].file.name))+c['output-suffix'])+'_'+ratio.replace(':','x')+'_'+(state.jobs.length+jobs.length+1)+'.'+format.ext;jobs.push({id:PixelCompat.id(),name,clips:group.map(v=>({...v})),config:PixelCompat.copySettings(c),assets:{...state.assets},cues:PixelCompat.copySettings(state.cues),format,ratio,status:'等待',progress:0,error:''})}return jobs}
function renderTasks(){const list=$('task-list');list.replaceChildren();for(const job of state.jobs){const div=document.createElement('div');div.className='task';const name=document.createElement('strong');name.textContent=job.name;const meta=document.createElement('small');meta.textContent=job.status+(job.status==='处理中'?' · '+Math.round(job.progress*100)+'%':'')+(job.blob?' · '+size(job.blob.size):'');if(job.error){meta.textContent+=' · '+job.error;meta.className='error'}div.append(name,meta);if(job.status==='处理中'){const progress=document.createElement('progress');progress.max=1;progress.value=job.progress;div.append(progress)}const actions=document.createElement('div');actions.className='task-actions';if(job.url){const a=document.createElement('a');a.textContent='下载 ↓';a.href=job.url;a.download=job.name;actions.append(a,button('原片 / 成片对比',()=>compareJob(job)),button('回看成片',()=>{let v=div.querySelector('video');if(v){v.pause();v.remove();return}v=document.createElement('video');v.controls=true;v.playsInline=true;v.src=job.url;div.append(v)}))}if(job.status==='失败'||job.status==='已取消'){const retry=button('单独重试',()=>runJobs([job]));retry.disabled=state.busy;actions.append(retry)}div.append(actions);list.append(div)}$('task-badge').textContent=state.jobs.length;$('download-all').disabled=state.busy||!state.jobs.some(j=>j.status==='成功')}
async function runJobs(jobs){if(state.busy)return;let audioContext,wake;try{if(!window.AudioContext||!window.MediaRecorder)throw Error('当前浏览器不支持合成，请使用新版浏览器');if(document.hidden)throw Error('请保持页面前台再处理');audioContext=new AudioContext();const unlock=audioContext.resume();state.busy=true;state.controller=new AbortController();stopPreview();$('music-player').pause();for(const j of jobs){j.status='等待';j.error='';j.progress=0}lock();renderTasks();location.hash='tasks';await Promise.race([unlock,new Promise((_,reject)=>setTimeout(()=>reject(Error('音频启动超时，请重试')),8000))]);try{wake=await navigator.wakeLock?.request('screen')}catch{}for(const job of jobs){if(state.controller.signal.aborted)break;job.status='处理中';renderTasks();message('正在生成 '+job.name);let last=0;try{const out=await E.compose(job,audioContext,state.controller.signal,(fraction,note)=>{job.progress=fraction;if(performance.now()-last>600){last=performance.now();renderTasks();message(job.name+' · '+note)}});job.blob=out.blob;job.url=url(out.blob);job.status='成功';job.progress=1}catch(e){job.status=state.controller.signal.aborted?'已取消':'失败';job.error=e.message;if(document.hidden)state.controller.abort(new Error('页面切到后台，请保持前台后重试'))}renderTasks()}for(const j of jobs)if(j.status==='等待'){j.status='已取消';j.error='批次已停止'}message('本批次完成：'+jobs.filter(j=>j.status==='成功').length+' 成功，'+jobs.filter(j=>j.status!=='成功').length+' 项可重试')}catch(e){for(const j of jobs)if(j.status==='等待'||j.status==='处理中'){j.status='失败';j.error=e.message}message(e.message,true)}finally{try{await audioContext?.close();await wake?.release()}catch{}state.busy=false;state.controller=null;lock();renderTasks()}}
$('export').onclick=()=>{try{const jobs=snapshotJobs();state.jobs.push(...jobs);runJobs(jobs)}catch(e){message(e.message,true)}};
$('cancel').onclick=()=>state.controller?.abort(new DOMException('用户已取消','AbortError'));
// Scheme assets are stored only in this browser, with the transaction completion as the success boundary.
function db(){return new Promise((resolve,reject)=>{const req=indexedDB.open('pixel-toolbox',1);req.onupgradeneeded=()=>req.result.createObjectStore('schemes',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function database(mode,fn){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('schemes',mode);let data;const req=fn(tx.objectStore('schemes'));req.onsuccess=()=>data=req.result;tx.oncomplete=()=>{d.close();resolve(data)};tx.onerror=tx.onabort=()=>{d.close();reject(tx.error||Error('方案保存失败，可能空间不足'))}})}
async function renderPresets(){try{const records=await database('readonly',s=>s.getAll());$('preset-list').replaceChildren();if(!records.length){$('preset-list').textContent='尚未保存方案';return}for(const p of records){const row=document.createElement('div');row.className='preset';const name=document.createElement('strong');name.textContent=p.name;const actions=document.createElement('div');actions.className='preset-actions';actions.append(button('应用方案',()=>loadPreset(p)),button('删除',async()=>{try{await database('readwrite',s=>s.delete(p.id));renderPresets()}catch(e){message(e.message,true)}}));row.append(name,actions);$('preset-list').append(row)}}catch(e){$('preset-list').textContent='无法使用浏览器方案存储：'+e.message}}
async function loadPreset(p){if(state.busy)return;state.loading++;lock();try{const assets={};for(const[k,f]of Object.entries(p.assets))assets[k]=await prepareAsset(k,f);const cues=E.parseSRT(p.srt);for(const id of configIds){const input=$(id);if(input.type==='checkbox')input.checked=!!p.config[id];else input.value=p.config[id]}document.querySelectorAll('[name=ratio]').forEach(n=>n.checked=p.config.ratios.includes(n.value));document.querySelectorAll('[name=format]').forEach(n=>n.checked=n.dataset.unsupported!=='true'&&p.config.formats.includes(n.dataset.ext));state.assets=assets;state.srt=p.srt;state.cues=cues;$('srt-text').value=p.srt;$('srt-state').textContent='已应用 '+cues.length+' 条字幕';$('preset-name').value=p.name;setLabels();renderAssets();estimate();await refreshPreview();message('已应用方案「'+p.name+'」。请选择本次源视频。')}catch(e){message(e.message,true)}finally{state.loading--;lock()}}
$('save-preset').onclick=async()=>{try{const c=validate(config());const name=$('preset-name').value.trim();if(!name)throw Error('请填写方案名称');const assets={};for(const[k,a]of Object.entries(state.assets))assets[k]=a.file;await database('readwrite',s=>s.put({id:PixelCompat.id(),name,config:c,assets,srt:state.srt}));message('方案已保存到此浏览器');renderPresets()}catch(e){message('未保存：'+e.message,true)}};
$('save-cover').onclick=async()=>{try{const p=state.preview;if(!p)throw Error('请先添加视频并选择封面帧');stopPreview();const c=config(),basis=c['export-mode']==='batch'&&p.segment.kind==='clip'?p.segment:state.clips[0]||p.segment,[w,h]=E.dimensions(basis.width,basis.height,$('preview-ratio').value,c.resolution);const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;E.draw(canvas.getContext('2d'),p.source,w,h,c,state.assets,p.segment,previewOffset()+Math.max(0,(p.video?.currentTime||0)-(p.segment.start||0)),state.cues,true);const blob=await new Promise(r=>canvas.toBlob(r,c['cover-format'],.95));if(!blob||blob.type!==c['cover-format'])throw Error('当前浏览器不支持所选封面格式');download(blob,safe(base(p.segment.file.name))+'_封面.'+blob.type.split('/')[1].replace('jpeg','jpg'));message('封面已生成')}catch(e){message(e.message,true)}};
function download(blob,name){const a=document.createElement('a');a.href=url(blob);a.download=name;a.click()}
$('clip-upload').onchange=e=>{addClips([...e.target.files]);e.target.value=''};$('drop-zone').ondragover=e=>{e.preventDefault();$('drop-zone').classList.add('drag')};$('drop-zone').ondragleave=()=>$('drop-zone').classList.remove('drag');$('drop-zone').ondrop=e=>{e.preventDefault();$('drop-zone').classList.remove('drag');addClips([...e.dataTransfer.files])};
for(const kind of ['mark','music','intro','outro'])$(kind+'-file').onchange=e=>{const file=e.target.files[0];e.target.value='';if(file)setAsset(kind,file)};
document.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>setAsset(b.dataset.clear,null));
$('preview-select').onchange=refreshPreview;$('preview-ratio').onchange=drawPreview;$('compare').onchange=()=>{$('original-wrap').hidden=!$('compare').checked||!state.preview?.video;$('preview-grid').classList.toggle('comparing',$('compare').checked&&!!state.preview?.video)};
$('play').onclick=async()=>{const v=state.preview?.video;if(!v)return;try{if(v.paused){await v.play();$('play').textContent='暂停';drawPreview()}else stopPreview()}catch(e){message(e.message,true)}};
$('seek').oninput=()=>{const v=state.preview?.video;if(v)v.currentTime=Number($('seek').value)/100*v.duration};
$('join-mode').onclick=()=>{$('export-mode').value='join';estimate();drawPreview();message('已切换为顺序拼接')};$('reset-trim').onclick=()=>{state.clips.forEach(v=>{v.start=0;v.end=v.duration});renderClips();estimate()};$('center-crop').onclick=()=>{const clip=state.clips.find(v=>v.id===$('preview-select').value);if(clip){clip.focusX=clip.focusY=.5;drawPreview()}};
$('apply-srt').onclick=applySRT;$('clear-srt').onclick=()=>{$('srt-text').value='';applySRT()};$('srt-file').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(f){try{$('srt-text').value=await f.text();applySRT()}catch(e){message(e.message,true)}}};
for(const id of configIds)$(id).addEventListener('input',()=>{setLabels();estimate();renderTimeline();drawPreview()});document.querySelectorAll('[name=ratio]').forEach(n=>n.onchange=estimate);
let drag=null;$('canvas').onpointerdown=e=>{if(state.busy||!state.preview)return;if(state.tool!=='watermark'&&state.tool!=='resize')return;const clip=state.clips.find(v=>v.id===state.preview.key);drag={x:e.clientX,y:e.clientY,fx:clip?.focusX??.5,fy:clip?.focusY??.5};$('canvas').setPointerCapture(e.pointerId);place(e)};function place(e){if(!drag)return;const rect=$('canvas').getBoundingClientRect(),c=config();if(state.tool==='watermark'){const m=E.markRect(rect.width,rect.height,c,state.assets.mark);$('mark-x').value=Math.round(Math.max(0,Math.min(100,(e.clientX-rect.left-m.w/2)/Math.max(1,rect.width-m.w)*100)));$('mark-y').value=Math.round(Math.max(0,Math.min(100,(e.clientY-rect.top-m.h/2)/Math.max(1,rect.height-m.h)*100)))}else if(c.fit==='cover'){const clip=state.clips.find(v=>v.id===state.preview.key);if(clip){const r=E.rectangle(clip.width,clip.height,rect.width,rect.height,'cover');if(r.w>rect.width+1)clip.focusX=Math.max(0,Math.min(1,drag.fx-(e.clientX-drag.x)/(r.w-rect.width)));if(r.h>rect.height+1)clip.focusY=Math.max(0,Math.min(1,drag.fy-(e.clientY-drag.y)/(r.h-rect.height)))}}drawPreview()}
$('canvas').onpointermove=place;$('canvas').onpointerup=$('canvas').onpointercancel=()=>drag=null;
for(const f of Studio.formats()){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.name='format';input.dataset.ext=f.ext;input.dataset.unsupported=String(!f.mime);input.disabled=!f.mime;input.checked=!!f.mime;input.onchange=estimate;label.append(input,document.createTextNode(f.label+(f.mime?'':' · 不支持')));$('formats').append(label)}
window.addEventListener('beforeunload',e=>{if(state.busy){e.preventDefault();e.returnValue=''}});window.addEventListener('unload',()=>urls.forEach(u=>URL.revokeObjectURL(u)));
setLabels();route();estimate();lock();

const crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});function crc32(a){let c=0xffffffff;for(const x of a)c=crcTable[(c^x)&255]^(c>>>8);return(c^0xffffffff)>>>0}
async function zipFiles(items){if(items.length>65535)throw Error("单次打包不能超过 65535 个文件");let offset=0;const local=[],central=[];const enc=new TextEncoder();for(const item of items){const name=enc.encode(item.name),data=new Uint8Array(await item.blob.arrayBuffer()),crc=crc32(data);if(offset+data.length>0xffffffff)throw Error('打包内容超过 4 GB，请分别下载');const h=new Uint8Array(30+name.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);h.set(name,30);local.push(h,data);const c=new Uint8Array(46+name.length),d=new DataView(c.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint32(16,crc,true);d.setUint32(20,data.length,true);d.setUint32(24,data.length,true);d.setUint16(28,name.length,true);d.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=h.length+data.length}const end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,items.length,true);ev.setUint16(10,items.length,true);ev.setUint32(12,central.reduce((s,a)=>s+a.length,0),true);ev.setUint32(16,offset,true);return new Blob([...local,...central,end],{type:'application/zip'})}

$('download-all').onclick=async()=>{const items=state.jobs.filter(j=>j.status==='成功').map(j=>({name:j.name,blob:j.blob}));if(!items.length)return;$('download-all').disabled=true;try{download(await zipFiles(items),'像素工坊_成片合集.zip');message('已打包 '+items.length+' 个成片')}catch(e){message(e.message,true)}finally{lock()}};

function compareJob(job){if(state.busy){message('请等待当前批次完成后对比成片');return}const area=$('compare-media');area.replaceChildren();for(const [label,src]of [['原片（首条源素材）',job.clips[0].url],['成片',job.url]]){const part=document.createElement('div'),name=document.createElement('p'),video=document.createElement('video');name.textContent=label;video.src=src;video.controls=true;video.playsInline=true;part.append(name,video);area.append(part)}$('compare-dialog').showModal()}
$('close-compare').onclick=()=>$('compare-dialog').close();$('compare-dialog').onclose=()=>{$('compare-media').querySelectorAll('video').forEach(v=>v.pause());$('compare-media').replaceChildren()};
